void add_box(float cx, float cy, float cz, float hx, float hy, float hz, __global float* out_pos, __global float* out_col, int* count, int max_vertices) {
    float temp_pos[108] = {
        -hx, -hy, hz,   hx, -hy, hz,   hx,  hy, hz,
        -hx, -hy, hz,   hx,  hy, hz,  -hx,  hy, hz,
        -hx, -hy, -hz, -hx,  hy, -hz,  hx,  hy, -hz,
        -hx, -hy, -hz,  hx,  hy, -hz,  hx, -hy, -hz,
        -hx, -hy, -hz, -hx, -hy, hz,  -hx,  hy, hz,
        -hx, -hy, -hz, -hx,  hy, hz,  -hx,  hy, -hz,
        hx, -hy, -hz,  hx,  hy, -hz,  hx,  hy, hz,
        hx, -hy, -hz,  hx,  hy, hz,   hx, -hy, hz,
        -hx,  hy, -hz, -hx,  hy, hz,   hx,  hy, hz,
        -hx,  hy, -hz,  hx,  hy, hz,   hx,  hy, -hz,
        -hx, -hy, -hz,  hx, -hy, -hz,  hx, -hy, hz,
        -hx, -hy, -hz,  hx, -hy, hz,  -hx, -hy, hz
    };
    int start = *count;
    for (int i = 0; i < 36; i++) {
        int idx = start + i;
        if (idx < max_vertices) {
            out_pos[idx * 3 + 0] = cx + temp_pos[i * 3 + 0];
            out_pos[idx * 3 + 1] = cy + temp_pos[i * 3 + 1];
            out_pos[idx * 3 + 2] = cz + temp_pos[i * 3 + 2];
            out_col[idx * 3 + 0] = 0.8f;
            out_col[idx * 3 + 1] = 0.2f;
            out_col[idx * 3 + 2] = 0.2f;
        }
    }
    *count = start + 36;
}

__kernel void process(__global const float* in_pos, __global const float* in_col, int in_count, __global float* out_pos, __global float* out_col, __global int* out_count, int max_vertices) {
    int id = get_global_id(0);
    if (id == 0) {
        float scale = chf("Scale", 1.0f);
        int wireframe = chb("Wireframe", 0);
        float dx = 0.5f * scale;
        float dy = 0.5f * scale;
        float dz = 0.5f * scale;
        float center_x = 0.0f;
        float center_y = 0.55f;
        float center_z = 0.0f;
        int count = 0;
        if (wireframe) {
            float t_line = 0.008f * scale;
            float t_corner = 0.012f * scale;
            for (int ix = 0; ix < 2; ix++) {
                float cx = center_x + (ix == 0 ? -dx : dx);
                for (int iy = 0; iy < 2; iy++) {
                    float cy = center_y + (iy == 0 ? -dy : dy);
                    for (int iz = 0; iz < 2; iz++) {
                        float cz = center_z + (iz == 0 ? -dz : dz);
                        add_box(cx, cy, cz, t_corner, t_corner, t_corner, out_pos, out_col, &count, max_vertices);
                    }
                }
            }
            for (int iy = 0; iy < 2; iy++) {
                float cy = center_y + (iy == 0 ? -dy : dy);
                for (int iz = 0; iz < 2; iz++) {
                    float cz = center_z + (iz == 0 ? -dz : dz);
                    add_box(center_x, cy, cz, dx, t_line, t_line, out_pos, out_col, &count, max_vertices);
                }
            }
            for (int ix = 0; ix < 2; ix++) {
                float cx = center_x + (ix == 0 ? -dx : dx);
                for (int iz = 0; iz < 2; iz++) {
                    float cz = center_z + (iz == 0 ? -dz : dz);
                    add_box(cx, center_y, cz, t_line, dy, t_line, out_pos, out_col, &count, max_vertices);
                }
            }
            for (int ix = 0; ix < 2; ix++) {
                float cx = center_x + (ix == 0 ? -dx : dx);
                for (int iy = 0; iy < 2; iy++) {
                    float cy = center_y + (iy == 0 ? -dy : dy);
                    add_box(cx, cy, center_z, t_line, t_line, dz, out_pos, out_col, &count, max_vertices);
                }
            }
        } else {
            add_box(center_x, center_y, center_z, dx, dy, dz, out_pos, out_col, &count, max_vertices);
        }
        *out_count = count;
    }
}
